"use client";
import { useRef } from "react";
import { typeInteractive, useTypeMotion, type TypographyMotionProps } from "./typography-shared";
import { typeEaseOut, typeStaggerProgress } from "./typography-math";
export interface RectangleTextRevealProps extends TypographyMotionProps {
  stagger?: number;
  maskColor?: string;
  radius?: number;
  direction?: "left" | "right";
}
export function RectangleTextReveal({
  text = "Keep moving.\nKeep discovering.\nMake every mile count.",
  stagger = 0.45,
  maskColor = "#e5e4e1",
  radius = 5,
  direction = "right",
  ...props
}: RectangleTextRevealProps) {
  const root = useRef<HTMLDivElement>(null);
  useTypeMotion(
    root,
    props,
    (p) => {
      const rows = Array.from(root.current!.querySelectorAll<HTMLElement>("[data-type-line]"));
      rows.forEach((row, i) => {
        const q = typeEaseOut(typeStaggerProgress(p, i, rows.length, stagger));
        const glyph = row.firstElementChild as HTMLElement,
          mask = row.lastElementChild as HTMLElement;
        glyph.style.transform = `translateY(${(1 - q) * 115}%)`;
        mask.style.transform = `scaleX(${1 - q})`;
      });
    },
    `${text}:${stagger}:${direction}`,
  );
  return (
    <div
      ref={root}
      className={props.className}
      style={props.style}
      aria-label={text}
      data-typography="rectangle-text-reveal"
      {...typeInteractive(props.trigger)}
    >
      <div aria-hidden="true">
        {text.split("\n").map((line, i) => (
          <div
            key={i}
            data-type-line=""
            style={{
              position: "relative",
              overflow: "hidden",
              width: "fit-content",
              maxWidth: "100%",
              borderRadius: radius,
              marginBlock: ".08em",
            }}
          >
            <span style={{ display: "block" }}>{line || "\u00a0"}</span>
            <span
              data-type-mask=""
              style={{
                position: "absolute",
                inset: 0,
                background: maskColor,
                borderRadius: radius,
                transform: "scaleX(0)",
                transformOrigin: direction === "right" ? "right" : "left",
              }}
            />
          </div>
        ))}
      </div>
    </div>
  );
}

// @zeus-internal
/** Grapheme splitting keeps accents and composed emoji in one animated unit. */
export function typeGraphemes(text: string): string[] {
  return typeof Intl.Segmenter === "function"
    ? Array.from(
        new Intl.Segmenter(undefined, { granularity: "grapheme" }).segment(text),
        (item) => item.segment,
      )
    : Array.from(text);
}
export const typeClamp = (n: number) => Math.max(0, Math.min(1, n));
export function typeStaggerProgress(progress: number, index: number, count: number, spread = 0.55) {
  const stagger = Math.max(0, Math.min(0.95, spread));
  return typeClamp((progress - (index / Math.max(1, count - 1)) * stagger) / (1 - stagger));
}
export const typeEaseOut = (p: number) => 1 - Math.pow(1 - typeClamp(p), 3);
export interface TypeGlyphIdentity {
  id: number;
  char: string;
}
/** Retain the nearest unused copy of each glyph, including repeated characters. */
export function typeMatchGlyphs(previous: TypeGlyphIdentity[], text: string): TypeGlyphIdentity[] {
  const used = new Set<number>();
  let nextId = Math.max(-1, ...previous.map((glyph) => glyph.id)) + 1;
  return typeGraphemes(text).map((char, index) => {
    const matches = previous
      .map((glyph, oldIndex) => ({ glyph, oldIndex }))
      .filter(({ glyph }) => glyph.char === char && !used.has(glyph.id))
      .sort((a, b) => Math.abs(a.oldIndex - index) - Math.abs(b.oldIndex - index));
    const match = matches[0]?.glyph;
    if (match) {
      used.add(match.id);
      return match;
    }
    return { char, id: nextId++ };
  });
}

