"use client";
import { useEffect, useRef, type CSSProperties, type RefObject } from "react";
import { typeClamp, typeGraphemes } from "./typography-math";

export type TypographyTrigger = "load" | "scroll" | "hover" | "click";
export interface TypographyMotionProps {
  text?: string;
  className?: string;
  style?: CSSProperties;
  trigger?: TypographyTrigger;
  /** Full sequence duration in seconds. */
  duration?: number;
  delay?: number;
  /** Scroll travel in pixels between hidden and fully revealed. */
  scrollDistance?: number;
  once?: boolean;
  /** Change this value to replay without remounting. */
  replayKey?: string | number;
  /** Optional controlled progress from zero to one. */
  progress?: number;
  onComplete?: () => void;
  onProgress?: (progress: number) => void;
}
export function TypeGlyphs({
  text,
  split = "chars",
}: {
  text: string;
  split?: "chars" | "words" | "lines";
}) {
  const parts =
    split === "chars"
      ? typeGraphemes(text)
      : split === "words"
        ? text.split(/(\s+)/)
        : text.split("\n");
  return (
    <>
      {parts.map((part, i) =>
        part === "\n" ? (
          <br key={i} />
        ) : (
          <span
            key={i}
            data-type-unit=""
            style={{
              display: split === "lines" ? "block" : "inline-block",
              whiteSpace: "pre",
              transformOrigin: "50% 100%",
            }}
          >
            {part || "\u00a0"}
          </span>
        ),
      )}
    </>
  );
}
export const typeUnits = (root: HTMLElement) =>
  Array.from(root.querySelectorAll<HTMLElement>("[data-type-unit]"));
export function typeScrollParent(element: HTMLElement): HTMLElement | null {
  let parent = element.parentElement;
  while (parent) {
    if (
      /(auto|scroll)/.test(getComputedStyle(parent).overflowY) &&
      parent.scrollHeight > parent.clientHeight
    )
      return parent;
    parent = parent.parentElement;
  }
  return null;
}
/** Instance-owned scheduling: hidden/offscreen work stops, font promises cannot revive an unmount. */
export function useTypeLoop<T extends HTMLElement>(
  root: RefObject<T | null>,
  draw: (time: number, delta: number, reduced: boolean) => void | boolean,
  key: string | number = "",
  enabled = true,
) {
  const latest = useRef(draw);
  latest.current = draw;
  useEffect(() => {
    const element = root.current;
    if (!element || !enabled) return;
    let disposed = false,
      frame = 0,
      visible = true,
      ready = false,
      elapsed = 0,
      last = 0;
    const media = matchMedia("(prefers-reduced-motion: reduce)");
    const ownsRoot = () => !disposed && root.current === element;
    const tick = (now: number) => {
      frame = 0;
      if (!ownsRoot() || !visible || document.hidden || !ready || media.matches) return;
      const delta = last ? Math.min(64, now - last) : 0;
      last = now;
      elapsed += delta;
      if (latest.current(elapsed, delta, false) !== false && ownsRoot())
        frame = requestAnimationFrame(tick);
    };
    const sync = () => {
      cancelAnimationFrame(frame);
      frame = 0;
      last = 0;
      if (!ownsRoot() || !ready) return;
      if (media.matches) latest.current(0, 0, true);
      else if (visible && !document.hidden) frame = requestAnimationFrame(tick);
    };
    const observer =
      typeof IntersectionObserver !== "undefined"
        ? new IntersectionObserver((entries) => {
            visible = entries[0]?.isIntersecting ?? true;
            sync();
          })
        : null;
    observer?.observe(element);
    media.addEventListener("change", sync);
    document.addEventListener("visibilitychange", sync);
    (document.fonts?.ready ?? Promise.resolve()).then(() => {
      if (ownsRoot()) {
        ready = true;
        sync();
      }
    });
    return () => {
      disposed = true;
      cancelAnimationFrame(frame);
      observer?.disconnect();
      media.removeEventListener("change", sync);
      document.removeEventListener("visibilitychange", sync);
    };
  }, [root, key, enabled]);
}
export function useTypeMotion<T extends HTMLElement>(
  root: RefObject<T | null>,
  options: TypographyMotionProps,
  draw: (progress: number, reduced: boolean) => void,
  contentKey = "",
) {
  const latest = useRef({ draw, onComplete: options.onComplete, onProgress: options.onProgress });
  latest.current = { draw, onComplete: options.onComplete, onProgress: options.onProgress };
  const controlled = useRef(options.progress);
  controlled.current = options.progress;
  const currentRender = useRef<((progress: number) => void) | null>(null);
  const {
    trigger = "load",
    duration = 1.2,
    delay = 0,
    once = true,
    replayKey,
    progress,
    scrollDistance,
  } = options;
  useEffect(() => {
    const element = root.current;
    if (!element) return;
    let disposed = false,
      frame = 0,
      ready = false,
      active = true,
      playing = false,
      elapsed = 0,
      last = 0,
      completed = false;
    const media = matchMedia("(prefers-reduced-motion: reduce)");
    const ownsRoot = () => !disposed && root.current === element;
    const scrollParent = typeScrollParent(element);
    const render = (value: number) => {
      if (!ready || !ownsRoot()) return;
      const p = media.matches ? 1 : typeClamp(value);
      latest.current.draw(p, media.matches);
      element.dataset.progress = String(p);
      latest.current.onProgress?.(p);
      if (p < 1 && !once) completed = false;
      if (p >= 1 && !completed) {
        completed = true;
        latest.current.onComplete?.();
      }
    };
    currentRender.current = render;
    const scroll = () => {
      if (controlled.current !== undefined) {
        render(controlled.current);
        return;
      }
      if (!ready || !ownsRoot() || document.hidden || (once && completed)) return;
      const rect = element.getBoundingClientRect(),
        bounds = scrollParent?.getBoundingClientRect();
      const height = scrollParent?.clientHeight ?? innerHeight;
      const top = rect.top - (bounds?.top ?? 0);
      render((height * 0.92 - top) / Math.max(80, scrollDistance ?? height * 0.65));
    };
    const tick = (now: number) => {
      frame = 0;
      if (!ownsRoot() || !ready || !active || document.hidden || !playing) return;
      if (controlled.current !== undefined) {
        playing = false;
        render(controlled.current);
        return;
      }
      elapsed += last ? Math.min(64, now - last) : 0;
      last = now;
      const p = (elapsed - delay * 1000) / Math.max(1, duration * 1000);
      render(p);
      if (p < 1 && ownsRoot()) frame = requestAnimationFrame(tick);
      else playing = false;
    };
    const start = () => {
      if (
        !ready ||
        !ownsRoot() ||
        controlled.current !== undefined ||
        (once && completed && trigger === "scroll")
      )
        return;
      cancelAnimationFrame(frame);
      elapsed = 0;
      last = 0;
      completed = false;
      playing = true;
      if (media.matches) render(1);
      else {
        render(0);
        frame = requestAnimationFrame(tick);
      }
    };
    const keydown = (event: KeyboardEvent) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        start();
      }
    };
    const sync = () => {
      cancelAnimationFrame(frame);
      frame = 0;
      last = 0;
      if (!ready || !ownsRoot()) return;
      if (media.matches) {
        render(1);
        return;
      }
      if (controlled.current !== undefined) {
        render(controlled.current);
        return;
      }
      if (trigger === "scroll") scroll();
      else if (playing && active && !document.hidden) frame = requestAnimationFrame(tick);
    };
    const observer =
      typeof IntersectionObserver !== "undefined"
        ? new IntersectionObserver((entries) => {
            active = entries[0]?.isIntersecting ?? true;
            sync();
          })
        : null;
    observer?.observe(element);
    media.addEventListener("change", sync);
    document.addEventListener("visibilitychange", sync);
    if (trigger === "hover") {
      element.addEventListener("pointerenter", start);
      element.addEventListener("focus", start);
    }
    if (trigger === "click") {
      element.addEventListener("click", start);
      element.addEventListener("keydown", keydown);
    }
    if (trigger === "scroll") {
      window.addEventListener("scroll", scroll, { passive: true });
      scrollParent?.addEventListener("scroll", scroll, { passive: true });
      window.addEventListener("resize", scroll);
    }
    (document.fonts?.ready ?? Promise.resolve()).then(() => {
      if (!ownsRoot()) return;
      ready = true;
      if (controlled.current !== undefined) render(controlled.current);
      else if (trigger === "load") start();
      else if (trigger === "scroll") scroll();
      else render(1);
    });
    return () => {
      disposed = true;
      currentRender.current = null;
      cancelAnimationFrame(frame);
      observer?.disconnect();
      media.removeEventListener("change", sync);
      document.removeEventListener("visibilitychange", sync);
      element.removeEventListener("pointerenter", start);
      element.removeEventListener("focus", start);
      element.removeEventListener("click", start);
      element.removeEventListener("keydown", keydown);
      window.removeEventListener("scroll", scroll);
      scrollParent?.removeEventListener("scroll", scroll);
      window.removeEventListener("resize", scroll);
    };
  }, [root, trigger, duration, delay, once, replayKey, scrollDistance, contentKey]);
  useEffect(() => {
    if (progress !== undefined) currentRender.current?.(progress);
  }, [progress]);
}
export function typeInteractive(trigger: TypographyTrigger | undefined) {
  return trigger === "click" || trigger === "hover" ? { tabIndex: 0, role: "button" as const } : {};
}
